mapper.sql:
FROM t_decision_release dr
JOIN t_decision_point dp ON dp.decision_point_id = dr.decision_point_id
WHERE dr.environment_code = 'TEST'

    AND dp.point_code = #{pointCode}


    AND dr.status = #{status}

mapper.update:
UPDATE t_decision_release
SET status = 'VALIDATING',
    version = 2,
    update_time = #{updateTime,jdbcType=TIMESTAMP,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler}
WHERE release_id = #{releaseId}
  AND status = #{expectedStatus}
  AND version = #{expectedVersion}

UPDATE t_decision_release
SET status = 'REJECTED',
    version = 3,
    update_time = #{updateTime,jdbcType=TIMESTAMP,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler}
WHERE release_id = #{releaseId}
  AND status = #{expectedStatus}
  AND version = #{expectedVersion}
